int main(void) {
    long long R, B;
    if (scanf("%lld %lld", &R, &B) != 2) return 0;

    // For K distinct non-empty boxes, the minimum total number of balls needed
    // is achieved by using the K distinct pairs:
    // (0,1), (1,0), (0,2), (1,1), (2,0), ...
    //
    // Let S = R + B.
    // The number of nonnegative pairs (r,b) with r+b <= t is:
    //   (t+1)(t+2)/2
    // Among them, excluding (0,0), there are:
    //   t(t+3)/2
    // distinct non-empty boxes.
    //
    // The total balls used by all non-empty pairs with r+b <= t is:
    //   t(t+1)(t+2)/3
    //
    // Therefore, if we take all boxes with sum <= t and then x boxes with sum t+1,
    // where 0 <= x <= t+2, then:
    //   K = t(t+3)/2 + x
    //   minimum total balls needed = t(t+1)(t+2)/3 + x*(t+1)
    //
    // Since colors can be arranged to match any R,B with total S
    // (by choosing suitable distinct pairs), the answer depends only on S.

    long long S = R + B;

    long long t = 0;
    while ((t + 1) * (t + 2) * (t + 3) / 3 <= S) t++;
    // Now t is the largest such that t(t+1)(t+2)/3 <= S

    long long baseBalls = t * (t + 1) * (t + 2) / 3;
    long long rem = S - baseBalls;
    long long x = rem / (t + 1);
    if (x > t + 2) x = t + 2;

    long long K = t * (t + 3) / 2 + x;
    printf("%lld\n", K);
    return 0;
}

