int main(){
    long long R, B;
    cin >> R >> B;
    long long T = R + B;

    // Binary search on K
    // min_total(K): pick K smallest pairs
    // Level n has (n+1) pairs each of cost n, for n=1,2,...

    auto min_total = [](long long K) -> long long {
        // fill levels
        long long total = 0;
        long long rem = K;
        for(long long n = 1; rem > 0; n++){
            long long cnt = min(rem, n+1);
            total += cnt * n;
            rem -= cnt;
        }
        return total;
    };

    long long lo = 1, hi = 200001, ans = 0;
    // max K is roughly O(sqrt(T))
    while(lo <= hi){
        long long mid = (lo+hi)/2;
        if(min_total(mid) <= T){ ans = mid; lo = mid+1; }
        else hi = mid-1;
    }
    cout << ans << endl;
}

