using int64 = long long;
using i128 = __int128_t;

static bool can(long long R, long long B, long long K) {
    // Need K distinct nonnegative pairs (r, b), excluding (0,0),
    // with sum r <= R and sum b <= B.
    //
    // For fixed K, among all sets of K distinct boxes, the minimum possible
    // total number of balls is achieved by taking points with smallest r+b.
    //
    // Let t be the largest fully taken layer, where layer s has s+1 points
    // (r+b=s), s>=1.
    // Sum_{s=1..t} (s+1) = t(t+3)/2 boxes.
    //
    // Then take x more points from layer t+1.
    //
    // To minimize required red and blue separately, among the x points on
    // layer t+1 we can choose consecutive points, minimizing one color sum.
    // Across all choices, feasibility reduces to:
    //   minimal possible red sum <= R
    //   minimal possible blue sum <= B
    // and total balls sum <= R+B automatically.
    //
    // For the full layers 1..t:
    //   red sum = blue sum = t(t+1)(t+2)/6

    long long t = 0;
    while ((i128)(t + 1) * (t + 4) / 2 <= K) t++;
    long long full = t * (t + 3LL) / 2;
    long long x = K - full; // 0 <= x <= t+2

    i128 base = (i128)t * (t + 1) * (t + 2) / 6;

    // On layer t+1, points are (0,t+1), (1,t), ..., (t+1,0).
    // Choosing x consecutive points minimizes one color sum.
    // Minimum additional red sum: 0+1+...+(x-1) = x(x-1)/2
    // Minimum additional blue sum: same.
    i128 needMin = base + (i128)x * (x - 1) / 2;

    // Also, since total on extra layer is x*(t+1), if red extra is a,
    // blue extra is x*(t+1)-a. By choosing consecutive points, every a in
    // [x(x-1)/2, x(2t+3-x)/2] is achievable, so feasibility is equivalent to
    // existence of a with:
    //   base + a <= R
    //   base + x*(t+1) - a <= B
    // i.e.
    //   a <= R-base
    //   a >= base + x*(t+1) - B
    // intersected with achievable interval.
    i128 loAch = (i128)x * (x - 1) / 2;
    i128 hiAch = (i128)x * (2LL * t + 3 - x) / 2;

    i128 low = max(loAch, base + (i128)x * (t + 1) - (i128)B);
    i128 high = min(hiAch, (i128)R - base);

    return low <= high;
}

