public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long R = sc.nextLong();
        long B = sc.nextLong();
        sc.close();

        long K = 0;
        long sum = 1;
        while (true) {
            long need = sum + 1;
            long pairsInThisSum = sum + 1;
            long redNeeded = 0, blueNeeded = 0;

            // We can take at most pairsInThisSum pairs from this sum level
            // but limited by remaining balls.
            // For sum s, pairs are (s,0),(s-1,1),...,(0,s)
            // To maximize count, we try to take as many as possible
            long take = Math.min(pairsInThisSum, R + B - (K + pairsInThisSum) + 1);
            if (take <= 0) break;

            // Check if we can actually take 'take' pairs given R and B
            // For sum s, the minimum reds needed for k pairs is 0,
            // maximum reds needed is s*k, but we need to check feasibility.
            long minR = 0, maxR = sum * take;
            // Actually we need to allocate distinct pairs; for take <= sum+1, it's always
            // possible to pick that many distinct pairs with red count between 0 and sum*take.
            // But we must also not exceed R and B.
            if (take > pairsInThisSum) take = pairsInThisSum;

            // Check if we have enough balls for 'take' pairs at this sum level
            long redAvailable = R;
            long blueAvailable = B;

            // Greedy: take as many as possible without exceeding R and B
            long possible = 0;
            for (long r = 0; r <= sum && possible < take; r++) {
                long b = sum - r;
                if (r <= redAvailable && b <= blueAvailable) {
                    possible++;
                    redAvailable -= r;
                    blueAvailable -= b;
                }
            }
            if (possible == 0) break;

            K += possible;
            R = redAvailable;
            B = blueAvailable;
            sum++;
        }

        System.out.println(K);
    }
}

