import java.io.*;
import java.util.*;

public class Main {
    static long R, B;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        R = fs.nextLong();
        B = fs.nextLong();

        long low = 0, high = 2_000_000_000L; // safely enough
        while (low < high) {
            long mid = (low + high + 1) >>> 1;
            if (can(mid)) low = mid;
            else high = mid - 1;
        }
        System.out.println(low);
    }

    static boolean can(long K) {
        // Need K distinct non-empty pairs (r,b), r,b >= 0, not both 0,
        // with total reds <= R and total blues <= B possible.
        //
        // For fixed K, let x = number of boxes with r=0 (blue-only),
        // and y = number of boxes with b=0 (red-only).
        // Then remaining z = K - x - y boxes have both colors positive.
        //
        // To minimize total red usage:
        // use blue-only boxes: (0,1),(0,2),...,(0,x)
        // and among the others choose smallest distinct positive red values:
        // red-only: (1,0),(2,0),...,(y,0)
        // both-positive: (1,1),(2,1),...,(z,1) if possible distinct from red-only by b=1
        // Hence minimal total reds for given y,z is sum(1..y)+sum(1..z).
        //
        // Similarly minimal blues is sum(1..x)+sum(1..z).
        //
        // So we need some x,y,z >= 0, x+y+z=K such that:
        // T(y)+T(z) <= R
        // T(x)+T(z) <= B
        // where T(n)=n(n+1)/2.
        //
        // Let z be chosen. Then we need:
        // x+y = K-z
        // T(y) <= R-T(z), T(x) <= B-T(z)
        // So maximum possible x+y is a+b where
        // a = max n with T(n) <= B-T(z)
        // b = max n with T(n) <= R-T(z)
        // and any split up to a+b is possible.
        // Therefore feasible iff for some z:
        // T(z)<=R, T(z)<=B, and K-z <= a+b.

        long maxZ = Math.min(invTri(R), invTri(B));
        if (maxZ > K) maxZ = K;

        // f(z) = z + invTri(R-T(z)) + invTri(B-T(z))
        // Need f(z) >= K for some z in [0,maxZ].
        // This function is unimodal enough for ternary-like search over integers? To keep safe,
        // use local hill-climb via ternary on discrete concave-like function and check neighborhood.
        long lo = 0, hi = maxZ;
        while (hi - lo > 6) {
            long m1 = lo + (hi - lo) / 3;
            long m2 = hi - (hi - lo) / 3;
            long f1 = value(m1);
            long f2 = value(m2);
            if (f1 <= f2) lo = m1;
            else hi = m2;
        }
        long best = 0;
        for (long z = lo; z <= hi; z++) best = Math.max(best, value(z));
        return best >= K;
    }

    static long value(long z) {
        long tz = tri(z);
        if (tz > R || tz > B) return Long.MIN_VALUE / 4;
        long a = invTri(R - tz);
        long b = invTri(B - tz);
        return z + a + b;
    }

    static long tri(long n) {
        return n * (n + 1) / 2;
    }

    static long invTri(long x) {
        // largest n with n(n+1)/2 <= x
        long lo = 0, hi = 2_000_000_000L;
        while (lo < hi) {
            long mid = (lo + hi + 1) >>> 1;
            if (mid <= 0 || triOverflowCheck(mid, x)) lo = mid;
            else hi = mid - 1;
        }
        return lo;
    }

    static boolean triOverflowCheck(long n, long x) {
        // check n(n+1)/2 <= x without overflow
        if ((n & 1) == 0) {
            return (n / 2) <= x / (n + 1);
        } else {
            return n <= (x / ((n + 1) / 2));
        }
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

import sys

def can_make(K, R, B):
    # Minimum total balls needed for K distinct non-empty boxes is 1+2+...+K
    if K * (K + 1) // 2 > R + B:
        return False

    # To maximize the number of boxes using at most R red balls,
    # use boxes (1,0), (2,0), ..., (x,0), needing x(x+1)/2 red.
    # So the maximum possible count of red-only boxes is:
    x = (int((8 * R + 1) ** 0.5) - 1) // 2
    while (x + 1) * (x + 2) // 2 <= R:
        x += 1
    while x * (x + 1) // 2 > R:
        x -= 1

    # Similarly for blue-only boxes.
    y = (int((8 * B + 1) ** 0.5) - 1) // 2
    while (y + 1) * (y + 2) // 2 <= B:
        y += 1
    while y * (y + 1) // 2 > B:
        y -= 1

    # If x + y >= K, we can choose K distinct boxes among
    # red-only and blue-only boxes, all non-empty and pairwise distinct.
    return x + y >= K

